    source: 'Patrick Radden Keefe, \'Empire of Pain\' (2021); U.S. v. Purdue Frederick Co. guilty plea (2007); Purdue guilty plea (Nov 2020); Harrington v. Purdue Pharma (U.S. Supreme Court, 2024)',
