    source: 'David Graham testimony, U.S. Senate Finance Committee (18 Nov 2004); Vioxx litigation documents (In re Vioxx Products Liability, E.D. La.); JAMA, \'Guest Authorship and Ghostwriting in Publications Related to Rofecoxib\' (2008)',
