    start: 2017,
    description: 'Discovery in the Dewayne Johnson lawsuit forced Monsanto to hand over internal emails showing it ghost-wrote the \'independent\' safety reviews of glyphosate (the most used herbicide on earth, sprayed on wheat as a pre-harvest desiccant so it is in nearly every loaf of bread), that an EPA official promised to kill a health-agency review (\'if I can kill this I should get a medal\'), and that executives privately wrote \'you cannot say that Roundup is not a carcinogen...',
