export interface Waypoint {
  lng: number;
  lat: number;
  locationName: string;
  description: string;
  year?: number;       // Approximate biblical year (negative for BC, positive for AD)
  displayDate?: string; // Human readable date label
}

export interface TravelPath {
  figureId: string;
  name: string;
  waypoints: Waypoint[];
}

